namespace BookStay.API.DTOs.Auth;

/// <summary>
/// Data Transfer Object (DTO) returned after successful user registration.
/// This DTO is sent back to the client to confirm the user was created successfully.
/// It contains the user's ID and basic information (but NOT the password for security).
/// </summary>
public class RegisteredUserDto
{
    /// <summary>
    /// The unique identifier for the user in the database.
    /// This is a GUID (Globally Unique Identifier) generated by ASP.NET Identity.
/// 
/// Technical: The Id is used to reference this user in other parts of the system.
/// Initialized to string.Empty to prevent null reference issues.
/// </summary>
    public string Id { get; set; } = string.Empty;

    /// <summary>
    /// The user's email address.
/// 
/// Technical: This is the email used for login and communication.
/// Initialized to string.Empty to prevent null reference issues.
/// </summary>
    public string Email { get; set; } = string.Empty;

    /// <summary>
    /// The user's first name (optional).
/// 
/// Technical: The '?' indicates this is a nullable string,
/// meaning it can be null if the user didn't provide a first name.
/// </summary>
    public string? FirstName { get; set; }

    /// <summary>
    /// The user's last name (optional).
/// 
/// Technical: Same as FirstName - nullable string allows null values.
/// </summary>
    public string? LastName { get; set; }
}
